#!/usr/bin/env python3
"""V8 P/B source probe: locate consolidated equity/net-worth lines in PIT annual reports.

This is deliberately a discovery diagnostic, not a production number extractor.
For representative NIFTY heavyweights it:
  * fetches the latest official NSE annual report available by 31-Aug-2026;
  * downloads that official report;
  * extracts text pages with consolidated balance-sheet / equity / net-worth
    vocabulary using pdfplumber;
  * records short page-local snippets and candidate numeric lines.

No candidate is chosen by closeness to published NIFTY P/B. OCR is not used.
A parse failure causes a fresh re-download before the company is marked failed,
so a transient truncated CDN response is not silently treated as source absence.
"""
from __future__ import annotations
from datetime import datetime, timezone
from io import BytesIO
from pathlib import Path
import json, re, time
import pandas as pd
import pdfplumber, requests

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'data'/'current_definition_v8_annual_report_probe.json'
ANCHOR=pd.Timestamp('2026-08-31 23:59:59')
SYMBOLS=['RELIANCE','HDFCBANK','ICICIBANK','INFY','TCS','SBIN','BHARTIARTL','LT']
API='https://www.nseindia.com/api/annual-reports'
UA={
 'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36',
 'Accept':'application/json,text/plain,*/*','Accept-Language':'en-US,en;q=0.9',
}


def session():
    s=requests.Session();s.headers.update(UA)
    for u in ('https://www.nseindia.com/','https://www.nseindia.com/companies-listing/corporate-filings-annual-reports'):
        try:s.get(u,timeout=20);time.sleep(.3)
        except Exception:pass
    return s


def dt(x):
    if not x:return None
    d=pd.to_datetime(str(x),dayfirst=True,errors='coerce')
    return None if pd.isna(d) else d


def report_rows(s,symbol):
    p={'index':'equities','symbol':symbol};last=None
    for attempt in range(5):
        try:
            r=s.get(API,params=p,headers={**UA,'Referer':f'https://www.nseindia.com/companies-listing/corporate-filings-annual-reports?symbol={symbol}&tabIndex=equity'},timeout=30)
            if r.status_code in (401,403,500):
                try:s.get('https://www.nseindia.com/',timeout=15)
                except Exception:pass
                time.sleep(1+attempt);continue
            r.raise_for_status();d=r.json()
            if isinstance(d,list):return d
            if isinstance(d,dict):
                if isinstance(d.get('data'),list):return d['data']
                rows=[]
                for v in d.values():
                    if isinstance(v,list):rows.extend(x for x in v if isinstance(x,dict))
                return rows
            return []
        except Exception as e:last=e;time.sleep(1+attempt)
    raise last or RuntimeError('annual_report_api_failed')


def broadcast(r):
    for k in ('broadcast_dttm','broadcastDate','broadcastDateTime','disseminationDateTime','date'):
        d=dt(r.get(k))
        if d is not None:return d
    return None


def url_of(r):
    for k in ('fileName','file_name','attachment','attchmntFile','url'):
        v=r.get(k)
        if isinstance(v,str) and v.startswith('http'):return v
    return None


def year_key(r):
    vals=[]
    for k in ('fromYear','from_year','fromYr','fromyear','toYear','to_year','toYr','toyear'):
        try:vals.append(int(r.get(k)))
        except Exception:pass
    return max(vals) if vals else -1


def latest_pit(rows):
    q=[]
    for r in rows:
        b=broadcast(r);u=url_of(r)
        if b is not None and b<=ANCHOR and u:q.append((year_key(r),b,r,u))
    if not q:return None
    q.sort(key=lambda x:(x[0],x[1]),reverse=True)
    _,b,r,u=q[0];return {'broadcast':str(b),'url':u,'raw':r}


def download_pdf(s,url,attempt=0):
    headers={**UA,'Referer':'https://www.nseindia.com/'}
    if attempt:headers['Cache-Control']='no-cache'
    r=s.get(url,headers=headers,timeout=80);r.raise_for_status()
    data=r.content
    if len(data)<1024:raise ValueError('annual_report_response_too_small')
    if data[:4]==b'%PDF':return data,'pdf'
    if data[:2]==b'PK':
        import zipfile
        z=zipfile.ZipFile(BytesIO(data));names=[n for n in z.namelist() if n.lower().endswith('.pdf')]
        if not names:raise ValueError('annual_report_zip_without_pdf')
        # Official annual-report package should contain the report PDF; choose the
        # largest PDF, not a ratio-fitting file.
        name=max(names,key=lambda n:z.getinfo(n).file_size)
        return z.read(name),'zip:'+name
    raise ValueError('annual_report_not_pdf_or_zip')

KEYWORDS=('consolidated balance sheet','consolidated statement of financial position','total equity','net worth','networth','equity attributable to owners','other equity')
NUMERIC_LINE=re.compile(r'.*(?:total equity|net\s*worth|networth|other equity|equity attributable).*\d.*',re.I)


def probe_pdf(pdf):
    hits=[]
    with pdfplumber.open(BytesIO(pdf)) as doc:
        pages=len(doc.pages)
        for i,p in enumerate(doc.pages):
            text=p.extract_text() or ''
            low=text.lower()
            if not any(k in low for k in KEYWORDS):continue
            lines=[re.sub(r'\s+',' ',x).strip() for x in text.splitlines() if x.strip()]
            cand=[x for x in lines if NUMERIC_LINE.match(x)]
            balance=any(k in low for k in ('consolidated balance sheet','consolidated statement of financial position'))
            anchor=next((j for j,x in enumerate(lines) if any(k in x.lower() for k in KEYWORDS)),0)
            snippet=lines[max(0,anchor-3):min(len(lines),anchor+9)]
            hits.append({'page':i+1,'has_consolidated_balance_sheet_heading':balance,'candidate_lines':cand[:12],'context_snippet':snippet})
            if len(hits)>=18:break
    return {'pages':pages,'hits':hits}


def download_and_probe(s,url,attempts=3):
    last=None
    for attempt in range(attempts):
        try:
            pdf,fmt=download_pdf(s,url,attempt)
            return pdf,fmt,probe_pdf(pdf),attempt+1
        except Exception as e:
            last=e
            try:s.get('https://www.nseindia.com/',timeout=15)
            except Exception:pass
            time.sleep(.8+attempt)
    raise last or RuntimeError('annual_report_probe_failed')


def main():
    s=session();out={};errors=[]
    for sym in SYMBOLS:
        try:
            rows=report_rows(s,sym);chosen=latest_pit(rows)
            if not chosen:raise ValueError('no_pit_annual_report')
            pdf,fmt,probe,attempts=download_and_probe(s,chosen['url'])
            out[sym]={'report_api_rows':len(rows),'chosen':chosen,'download_format':fmt,'download_attempts':attempts,'pdf_bytes':len(pdf),**probe}
        except Exception as e:errors.append({'symbol':sym,'error':f'{type(e).__name__}: {e}'})
        time.sleep(.4)
    result={'schema_version':2,'generated_at':datetime.now(timezone.utc).replace(microsecond=0).isoformat(),'research_only':True,
            'anchor_date':'2026-08-31','symbols':SYMBOLS,'coverage':{'ok':len(out),'required':len(SYMBOLS),'failed':len(errors)},'failed':errors,'cases':out,
            'selection_guardrail':'Latest PIT annual report by official year/broadcast metadata; PDF lines are surfaced semantically and are not selected by closeness to published NIFTY P/B.',
            'download_guardrail':'A PDF parse failure triggers up to three fresh downloads before source failure is recorded.',
            'pdfplumber_expected_version':'0.11.10','ocr_used':False,'live_model_changed':False,'live_allocation_changed':False,'tolerances_changed':False}
    OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps(result,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')
    print(json.dumps({'coverage':result['coverage'],'headline':{s:{'broadcast':v['chosen']['broadcast'],'pages':v['pages'],'download_attempts':v['download_attempts'],'hit_pages':[h['page'] for h in v['hits'][:8]],'candidate_lines':[x for h in v['hits'] for x in h['candidate_lines'][:2]][:8]} for s,v in out.items()},'failed':errors},indent=2,ensure_ascii=False))

if __name__=='__main__':main()

#!/usr/bin/env python3
"""V8 gate 1: independently verify the official NIFTY 50 valuation benchmark.

This calls Nifty Indices' P/E-P/B-Dividend Yield historical endpoint directly
and compares it with the maintained `jugaad_data.index_pe_raw` wrapper. It does
not reconstruct any constituent and does not modify the live model.

The gate fails if:
* the direct official endpoint does not return the requested 31-Aug-2026 row;
* the returned row cannot be parsed as PE/PB/DY;
* the direct official values disagree with the helper values beyond display
  precision (1e-9 after numeric conversion).
"""
from __future__ import annotations
from datetime import date, datetime, timezone
from pathlib import Path
import json, math, requests

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'data'/'current_definition_v8_benchmark.json'
ANCHOR=date(2026,8,31)
SYMBOL='NIFTY 50'
URL='https://niftyindices.com/BackPage/getpepbHistoricaldataDBtoString'

HEADERS={
 'Accept':'application/json, text/javascript, */*; q=0.01',
 'Content-Type':'application/json; charset=UTF-8',
 'Origin':'https://niftyindices.com',
 'Referer':'https://niftyindices.com/reports/historical-data',
 'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36',
 'X-Requested-With':'XMLHttpRequest',
}


def fnum(x):
    if x in (None,'','-'):return None
    try:return float(str(x).replace(',','').replace('%','').strip())
    except Exception:return None


def values(row):
    # The official endpoint has historically used lower-case pe/pb/divYield,
    # while wrappers and mirrors may expose display-key variants. Parse only
    # known semantic aliases; never infer by field order.
    aliases={
      'pe':['pe','PE','P/E','p_e'],
      'pb':['pb','PB','P/B','p_b'],
      'dy':['divYield','Div Yield','Div Yield %','Dividend Yield','DY','dy'],
    }
    out={}
    for k,names in aliases.items():
        v=None
        for n in names:
            if n in row:
                v=fnum(row.get(n))
                if v is not None:break
        out[k]=v
    return out


def row_date(row):
    for k in ('DATE','Date','date','HistoricalDate'):
        if row.get(k):return str(row.get(k))
    return None


def direct():
    cinfo={'name':SYMBOL,'startDate':ANCHOR.strftime('%d-%b-%Y'),'endDate':ANCHOR.strftime('%d-%b-%Y'),'indexName':SYMBOL}
    payload={'cinfo':str(cinfo).replace('"',"'")}
    s=requests.Session();s.headers.update(HEADERS)
    # Seed first-party cookies but do not depend on a cached helper response.
    try:s.get('https://niftyindices.com/reports/historical-data',timeout=20)
    except Exception:pass
    r=s.post(URL,json=payload,headers=HEADERS,timeout=40);r.raise_for_status()
    raw=r.json()
    if isinstance(raw,dict) and 'd' in raw:raw=raw['d']
    if isinstance(raw,str):raw=json.loads(raw)
    if not isinstance(raw,list) or not raw:raise RuntimeError('official_endpoint_empty')
    # Exact one-day request should normally return one row. If more are returned,
    # retain only rows whose date text identifies 31-Aug-2026.
    exact=[]
    for x in raw:
        ds=(row_date(x) or '').upper().replace(' ','')
        if any(t in ds for t in ('31-AUG-2026','31-AUG-26','31/08/2026','31-08-2026','2026-08-31')):exact.append(x)
    row=exact[0] if exact else raw[0] if len(raw)==1 else None
    if row is None:raise RuntimeError('official_anchor_row_ambiguous')
    vals=values(row)
    if not all(math.isfinite(float(vals[k])) for k in ('pe','pb','dy') if vals[k] is not None) or any(vals[k] is None for k in ('pe','pb','dy')):
        raise RuntimeError('official_ratio_parse_failed')
    return {'payload':payload,'http_status':r.status_code,'raw_row':row,'values':vals}


def helper():
    from jugaad_data.nse import index_pe_raw
    rows=index_pe_raw(SYMBOL,ANCHOR,ANCHOR) or []
    if not rows:raise RuntimeError('helper_empty')
    row=rows[0];vals=values(row)
    if any(vals[k] is None for k in ('pe','pb','dy')):raise RuntimeError('helper_ratio_parse_failed')
    return {'raw_row':row,'values':vals}


def main():
    d=direct();h=helper();delta={k:float(d['values'][k])-float(h['values'][k]) for k in ('pe','pb','dy')}
    agrees=all(abs(v)<=1e-9 for v in delta.values())
    if not agrees:raise RuntimeError('direct_official_and_helper_disagree: '+json.dumps(delta))
    out={
      'schema_version':1,'generated_at':datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
      'research_only':True,'anchor_date':ANCHOR.isoformat(),'symbol':SYMBOL,
      'official_endpoint':URL,'direct':d,'helper':h,'delta':delta,'agrees':agrees,
      'verified_benchmark':d['values'],
      'interpretation':'This validates only the published comparison target. It does not validate any constituent reconstruction formula.',
      'live_model_changed':False,'live_allocation_changed':False,'tolerances_changed':False,
    }
    OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps(out,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')
    print(json.dumps({'verified_benchmark':out['verified_benchmark'],'delta':delta,'agrees':agrees},indent=2))

if __name__=='__main__':main()

#!/usr/bin/env python3
"""V8 P/E gate: infer operational IWF using official shareholding XBRL total shares.

This is a falsification test, not an IWF estimator. For every 31-Aug-2026 NIFTY
50 constituent:
  effective IWF = official free-float index market cap / (price * total shares)
where total shares come independently from the 30-Jun-2026 official NSE
Shareholding Pattern XBRL.

The official public-shareholding percentage is a HARD UPPER BOUND on free-float
IWF, but the published percentage itself is rounded. A breach is therefore
recorded only when the entire displayed-rounding interval for implied IWF lies
above the upper end of the displayed public-shareholding rounding interval.
Public shareholding is never substituted as IWF.
"""
from __future__ import annotations
from datetime import datetime, timezone
from io import BytesIO
from pathlib import Path
import json, math, re, time, zipfile, xml.etree.ElementTree as ET
import pandas as pd
import pdfplumber, requests

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'data'/'current_definition_v8_iwf_bound.json'
WEIGHT_URL='https://www.niftyindices.com/Indices_-_Market_Capitalisation_and_Weightage/indices_dataAug2026.zip'
SH_API='https://www.nseindia.com/api/corporate-share-holdings-master'
UA={'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36','Accept':'*/*','Accept-Language':'en-US,en;q=0.9'}


def session():
    s=requests.Session();s.headers.update(UA)
    for u in ('https://www.nseindia.com/','https://www.niftyindices.com/'):
        try:s.get(u,timeout=20);time.sleep(.3)
        except Exception:pass
    return s


def weight_rows(s):
    r=s.get(WEIGHT_URL,headers={**UA,'Referer':'https://www.niftyindices.com/reports/monthly-reports'},timeout=40);r.raise_for_status()
    z=zipfile.ZipFile(BytesIO(r.content));name=next(n for n in z.namelist() if re.search(r'NIFTY_50_Aug2026\.pdf$',n,re.I));pdf=z.read(name)
    rows=[];header_text=''
    with pdfplumber.open(BytesIO(pdf)) as doc:
        for p in doc.pages:
            header_text += '\n'+(p.extract_text() or '')[:1200]
            tbl=p.extract_table() or []
            for rr in tbl[1:]:
                if not rr or len(rr)<6:continue
                try:
                    sym=str(rr[0] or '').strip();price=float(str(rr[3]).replace(',',''));mcap=float(str(rr[4]).replace(',',''));wt=float(str(rr[5]).replace(',',''))
                except Exception:continue
                if sym:rows.append({'symbol':sym,'price':price,'index_mcap_cr':mcap,'published_weight_pct':wt})
    rows=list({r['symbol']:r for r in rows}.values())
    if len(rows)!=50:raise RuntimeError(f'weight_count_{len(rows)}')
    if 'August 31, 2026' not in header_text and 'August 31 2026' not in header_text:raise RuntimeError('weight_pdf_anchor_date_not_verified')
    return rows,{'url':WEIGHT_URL,'pdf':name,'count':len(rows),'weight_sum':sum(x['published_weight_pct'] for x in rows)}


def dt(x):
    d=pd.to_datetime(str(x),dayfirst=True,errors='coerce')
    return None if pd.isna(d) else d


def share_rows(s,sym):
    p={'index':'equities','symbol':sym};last=None
    for attempt in range(5):
        try:
            r=s.get(SH_API,params=p,headers={**UA,'Referer':f'https://www.nseindia.com/companies-listing/corporate-filings-shareholding-pattern?symbol={sym}&tabIndex=equity'},timeout=30)
            if r.status_code in (401,403,500):
                try:s.get('https://www.nseindia.com/',timeout=15)
                except Exception:pass
                time.sleep(1+attempt);continue
            r.raise_for_status();d=r.json();return d if isinstance(d,list) else d.get('data',[]) if isinstance(d,dict) else []
        except Exception as e:last=e;time.sleep(1+attempt)
    raise last or RuntimeError('shareholding_api_failed')


def june(rows):
    for r in rows:
        d=dt(r.get('date') or r.get('asOnDate') or r.get('as_on_date'))
        if d is not None and d.date()==pd.Timestamp('2026-06-30').date():return r
    return None


def local(tag):return tag.split('}')[-1].split(':')[-1]


def xroot(s,url):
    last=None
    for a in range(6):
        try:
            r=s.get(url,headers={**UA,'Referer':'https://www.nseindia.com/companies-listing/corporate-filings-shareholding-pattern','Accept':'application/xml,text/xml,*/*'},timeout=40)
            if r.status_code in (401,403,500):
                try:s.get('https://www.nseindia.com/',timeout=15)
                except Exception:pass
                time.sleep(1+a*.6);continue
            r.raise_for_status();return ET.fromstring(r.content)
        except Exception as e:last=e;time.sleep(.7+a*.6)
    raise last or RuntimeError('shareholding_xbrl_failed')


def total_shares(root):
    candidates=[]
    for e in root.iter():
        if e.attrib.get('contextRef')!='ShareholdingPattern_ContextI':continue
        name=local(e.tag);txt=(e.text or '').strip()
        if name not in ('NumberOfShares','NumberOfFullyPaidUpEquityShares'):continue
        try:v=float(txt.replace(',',''))
        except Exception:continue
        if v>0:candidates.append((name,v,e.attrib.get('unitRef')))
    for preferred in ('NumberOfShares','NumberOfFullyPaidUpEquityShares'):
        vals=[x for x in candidates if x[0]==preferred]
        if vals:
            uniq={round(x[1],6) for x in vals}
            if len(uniq)!=1:raise ValueError('ambiguous_'+preferred)
            return vals[0]
    raise ValueError('aggregate_total_shares_missing')


def fnum(x):
    try:return float(str(x).replace(',','').replace('%','').strip())
    except Exception:return None


def decimals(x):
    s=str(x).replace('%','').strip();return len(s.split('.',1)[1]) if '.' in s else 0


def displayed_interval(x):
    """Return [lo, hi] consistent with ordinary rounding of a displayed value."""
    v=fnum(x)
    if v is None:return None
    half=.5*10**(-decimals(x))
    return max(0.0,v-half),min(100.0,v+half),half


def interval(row,shares):
    mc=float(row['index_mcap_cr']);px=float(row['price']);n=float(shares)
    mh=.5*10**(-decimals(row['index_mcap_cr']));ph=.5*10**(-decimals(row['price']))
    point=mc*1e7/(px*n)
    lo=max(0,mc-mh)*1e7/((px+ph)*n)
    hi=(mc+mh)*1e7/(max(1e-12,px-ph)*n)
    return point,lo,hi


def main():
    s=session();weights,wmeta=weight_rows(s);done=[];errors=[]
    for row in weights:
        sym=row['symbol']
        try:
            jr=june(share_rows(s,sym))
            if not jr:raise ValueError('june_2026_shareholding_missing')
            url=jr.get('xbrl')
            if not url:raise ValueError('shareholding_xbrl_missing')
            tag,shares,unit=total_shares(xroot(s,url));pub_raw=jr.get('public_val');pub=fnum(pub_raw);prom=fnum(jr.get('pr_and_prgrp'))
            pubint=displayed_interval(pub_raw)
            if pub is None or pubint is None:raise ValueError('public_shareholding_missing')
            publo,pubhi,pubhalf=pubint
            point,lo,hi=interval(row,shares)
            breach=bool(lo>pubhi/100.0)
            done.append({**row,'shareholding_total_shares':shares,'share_tag':tag,'share_unit':unit,
                         'public_pct':pub,'public_display_half_step_pp':pubhalf,'public_pct_min':publo,'public_pct_max':pubhi,
                         'promoter_pct':prom,'implied_iwf':point,'implied_iwf_min':lo,'implied_iwf_max':hi,
                         'public_minus_iwf_pp':pub-100*point,
                         'public_upper_minus_iwf_lower_pp':pubhi-100*lo,
                         'hard_upper_bound_breach':breach,'xbrl':url})
        except Exception as e:errors.append({'symbol':sym,'error':f'{type(e).__name__}: {e}'})
        time.sleep(.18)
    done=sorted(done,key=lambda x:x['symbol']);breach=[x for x in done if x['hard_upper_bound_breach']]
    tot=sum(x['index_mcap_cr'] for x in done) or 1
    out={'schema_version':2,'generated_at':datetime.now(timezone.utc).replace(microsecond=0).isoformat(),'research_only':True,
         'anchor_date':'2026-08-31','shareholding_quarter':'2026-06-30','weight_source':wmeta,
         'coverage':{'ok':len(done),'required':50,'failed':len(errors)},'failed':errors,
         'breaches':{'count':len(breach),'index_weight_pct':100*sum(x['index_mcap_cr'] for x in breach)/tot,'symbols':[x['symbol'] for x in breach]},
         'logic':'Public shareholding is only a hard upper bound and is never substituted as free-float IWF. Both the price/market-cap inputs and the displayed public-shareholding percentage are treated as rounded. A hard breach is recorded only if the minimum implied IWF exceeds the maximum public shareholding consistent with displayed precision.',
         'constituents':done,'live_model_changed':False,'live_allocation_changed':False,'tolerances_changed':False}
    OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps(out,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')
    print(json.dumps({'coverage':out['coverage'],'breaches':out['breaches'],
                      'worst_upper_bound_margins':sorted([{'symbol':x['symbol'],'public_upper_minus_iwf_lower_pp':x['public_upper_minus_iwf_lower_pp'],'weight_pct':x['published_weight_pct']} for x in done],key=lambda z:z['public_upper_minus_iwf_lower_pp'])[:12]},indent=2))

if __name__=='__main__':main()

